    "definitions": [
        {
            "word": "absolute word",
            "meaning": "كلمة قطعية / تعبير جازم",
            "definition": "A word that expresses no doubt or exception, such as \"always\", \"never\", or \"completely\"."
        },
        {
            "word": "bias",
            "meaning": "انحياز / تحيز",
            "definition": "An inclination or unfair preference towards one perspective over another."
        },
        {
            "word": "biased language",
            "meaning": "لغة متحيزة / ألفاظ غير محايدة",
            "definition": "Words and phrases that show clear partiality, prejudice, or loaded emotional judgment."
        },
        {
            "word": "evaluative adjective",
            "meaning": "صفة تقييمية (حُكمية)",
            "definition": "An adjective that expresses personal opinion or judgment rather than an objective factual description."
        },
        {
            "word": "hedging word",
            "meaning": "كلمة تحوط / تعبير احترازي",
            "definition": "Cautious language used to soften statements and avoid absolute claims (e.g., \"suggests\", \"tends to\", \"possibly\")."
        },
        {
            "word": "highlight-reel effect",
            "meaning": "أثر استعراض أفضل اللحظات",
            "definition": "The psychological bias of comparing one's daily reality to the curated, best moments shown on social media."
        },
        {
            "word": "intensifier",
            "meaning": "أداة توكيد / لفظ مشدد",
            "definition": "A word (like \"extremely\", \"absolutely\", \"deeply\") used to strengthen the force or degree of an adjective or verb."
        },
        {
            "word": "neutral language",
            "meaning": "لغة محايدة / أسلوب موضوعي",
            "definition": "Objective, fact-based words without emotional coloring or subjective prejudice."
        },
        {
            "word": "rhetorical question",
            "meaning": "سؤال بلاغي",
            "definition": "A question asked to make a point or stimulate thought rather than to elicit a literal answer."
        },
        {
            "word": "social comparison",
            "meaning": "المقارنة الاجتماعية",
            "definition": "The psychological tendency to judge one's own abilities, success, or appearance against those of others."
        }
    ],
